script:
out = {}
def walk(path, depth):
    if depth > 3:
        return
    for entry in repo.list(path):
        p = entry if path == "." else path + "/" + entry
        out[p] = True
        if entry.endswith("/"):
            walk(p.rstrip("/"), depth + 1)
walk(".", 0)
return sorted(out.keys())

